{"tool": "submit_job", "args": {"source": "import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { pathToFileURL } from "node:url";

export async function gate({ referenceDir, submissionDir }) {
  try {
    const submissionPath = path.join(submissionDir, "answer.mjs");
    const pinnedPath = path.join(referenceDir, "pinned-test-cases.txt");
    if (!fs.existsSync(submissionPath)) {
      return { accept: false, reason: "missing answer.mjs" };
    }
    let pinned = "";
    if (fs.existsSync(pinnedPath)) {
      pinned = fs.readFileSync(pinnedPath, "utf8");
    }
    if (!pinned.trim()) {
      return { accept: false, reason: "missing pinned test cases" };
    }
    const subUrl = pathToFileURL(submissionPath).href;
    const runnerPath = path.join(referenceDir, "_gate_runner.mjs");
    const nl = String.fromCharCode(10);
    const runner = [
      "import { test } from 'node:test';",
      "import assert from 'node:assert/strict';",
      "import { dedupeSorted } from " + JSON.stringify(subUrl) + ";",
      pinned
    ].join(nl);
    fs.writeFileSync(runnerPath, runner, "utf8");
    const result = spawnSync(process.execPath, ["--test", runnerPath], {
      encoding: "utf8",
      timeout: 20000
    });
    if (result.status === 0) {
      return { accept: true, reason: "pinned tests passed" };
    }
    const output = ((result.stdout || "") + nl + (result.stderr || "")).slice(0, 2000);
    return { accept: false, reason: "pinned tests failed: " + output };
  } catch (err) {
    return { accept: false, reason: "gate error: " + (err && err.message ? err.message : String(err)) };
  }
}
